package repository

import (
	"context"
	"database/sql"
	"embed"
	"fmt"
	"io/fs"
	"sort"
	"strings"
)

// migrationsFS embeds the migration copies generated by
// tools/scripts/gen-migrations.sh. The SSOT lives at data/sqlite/migrations/;
// //go:embed cannot reach outside the module root, so the CI script keeps this
// directory in sync (tools/ci/verify-migrations.sh fails on drift).
//
//go:embed migrations/*.sql
var migrationsFS embed.FS

// ApplyMigrations executes every embedded migration file in lexical (filename)
// order. Files are ordered so 001_ initial, 002_ ... apply deterministically.
// Migrations are written idempotently (IF NOT EXISTS) so re-running is safe.
func ApplyMigrations(ctx context.Context, db *sql.DB) error {
	entries, err := fs.ReadDir(migrationsFS, "migrations")
	if err != nil {
		return fmt.Errorf("read embedded migrations: %w", err)
	}

	names := make([]string, 0, len(entries))
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".sql") {
			continue
		}
		names = append(names, e.Name())
	}
	sort.Strings(names)

	for _, name := range names {
		content, err := migrationsFS.ReadFile("migrations/" + name)
		if err != nil {
			return fmt.Errorf("read migration %s: %w", name, err)
		}
		for _, stmt := range splitStatements(string(content)) {
			if _, err := db.ExecContext(ctx, stmt); err != nil {
				return fmt.Errorf("apply migration %s: %w", name, err)
			}
		}
	}
	return nil
}

// splitStatements splits a SQL script into individual statements on
// semicolons that are not inside string/identifier literals or line comments.
// This keeps the runner independent from driver-specific multi-statement
// support and lets each statement fail with a precise error.
func splitStatements(script string) []string {
	var (
		stmts   []string
		current strings.Builder
		inLine  bool // inside -- line comment
		inSgl   bool // inside '...'
		inDbl   bool // inside "..."
	)

	runes := []rune(script)
	for i := 0; i < len(runes); i++ {
		c := runes[i]

		if inLine {
			if c == '\n' {
				inLine = false
				current.WriteRune(c)
			}
			continue
		}
		if inSgl {
			current.WriteRune(c)
			if c == '\'' {
				// Handle doubled '' escape.
				if i+1 < len(runes) && runes[i+1] == '\'' {
					current.WriteRune(runes[i+1])
					i++
				} else {
					inSgl = false
				}
			}
			continue
		}
		if inDbl {
			current.WriteRune(c)
			if c == '"' {
				if i+1 < len(runes) && runes[i+1] == '"' {
					current.WriteRune(runes[i+1])
					i++
				} else {
					inDbl = false
				}
			}
			continue
		}

		switch {
		case c == '-' && i+1 < len(runes) && runes[i+1] == '-':
			inLine = true
			i++
		case c == '\'':
			inSgl = true
			current.WriteRune(c)
		case c == '"':
			inDbl = true
			current.WriteRune(c)
		case c == ';':
			if s := strings.TrimSpace(current.String()); s != "" {
				stmts = append(stmts, s)
			}
			current.Reset()
		default:
			current.WriteRune(c)
		}
	}

	if s := strings.TrimSpace(current.String()); s != "" {
		stmts = append(stmts, s)
	}
	return stmts
}
